function manage(mode){vaultMode=mode;$('manage-title').textContent=mode==='add'?'웹앱 추가':'개인 링크 보관함';$('app-name').parentElement.querySelectorAll('label[for="app-name"],label[for="app-url"],#app-name,#app-url').forEach(e=>e.hidden=mode!=='add');$('app-name').required=$('app-url').required=mode==='add';$('app-url').nextElementSibling.hidden=mode!=='add';$('password-area').hidden=!!password;$('vault-password').required=!password;$('vault-password').value='';$('form-error').textContent='';$('app-name').value='';$('app-url').value='';$('save-app').hidden=mode!=='add'&&!!password;$('save-app').textContent=mode==='add'?'암호화해 추가':'잠금 해제 / 보관함 만들기';$('vault-actions').hidden=mode==='add';$('vault-state').textContent=password?'잠금 해제됨 · 이 열린 화면에서만 비밀번호를 기억해요.':'잠김 · 비밀번호를 입력하면 개인 링크가 표시됩니다.';$('password-help').textContent='기존 보관함이 있으면 같은 비밀번호를 입력하세요. 저장 데이터가 없으면 새 보관함을 만듭니다.';$('manage-dialog').showModal();}
$('add-button').onclick=()=>manage('add');$('backup-button').onclick=()=>manage('vault');$('vault-button').onclick=()=>{if(password)lock();else manage('vault');};$('close-manage').onclick=()=>{if(!vaultBusy)$('manage-dialog').close();};$('manage-dialog').addEventListener('cancel',e=>{if(vaultBusy)e.preventDefault();});$('manage-dialog').addEventListener('close',()=>{$('vault-password').value='';$('app-name').value='';$('app-url').value='';});
$('app-form').onsubmit=async e=>{e.preventDefault();if(vaultBusy)return;vaultBusy=true;$('save-app').disabled=true;$('form-error').textContent='';try{const generation=vaultGeneration;if(!password){const candidate=$('vault-password').value;const existing=localStorage.getItem('drawer-vault');const restored=existing?await decryptVault(JSON.parse(existing),candidate):[];if(generation!==vaultGeneration)throw Error('보관함 상태가 바뀌었어요. 다시 시도해 주세요.');password=candidate;custom=restored;vaultRaw=existing;if(!existing)await persist([]);}$('vault-password').value='';if(vaultMode==='add'){const added={id:crypto.randomUUID(),name:$('app-name').value.trim(),url:safeUrl($('app-url').value)};const next=[...custom,added];await persist(next);custom=next;toast('웹앱을 암호화해 보관했어요.');}else toast('보관함 잠금을 해제했어요.');render();$('manage-dialog').close();}catch(e){$('form-error').textContent=e.name==='OperationError'?'비밀번호가 다르거나 보관함이 손상됐어요. 기존 데이터는 그대로입니다.':e.message||'저장하지 못했어요. 기존 보관함은 유지됩니다.';}finally{vaultBusy=false;idleReset();$('save-app').disabled=false;}};
$('lock-vault').onclick=()=>{if(vaultBusy)return;lock();$('manage-dialog').close();};$('export-vault').onclick=()=>{try{const data=localStorage.getItem('drawer-vault');if(!data){toast('아직 저장된 보관함이 없어요.');return;}const blob=new Blob([data],{type:'application/json'}),url=URL.createObjectURL(blob),a=node('a');a.href=url;a.download='classroom-drawer-encrypted.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('암호화 백업을 저장했어요.');}catch{toast('백업 파일을 만들지 못했어요.');}};
$('import-vault').onclick=()=>{if(!password){toast('먼저 현재 보관함을 잠금 해제하거나 같은 비밀번호로 만들어 주세요.');return;}$('import-file').click();};$('import-file').onchange=async()=>{const f=$('import-file').files[0];$('import-file').value='';if(!f)return;if(vaultBusy){toast('저장 처리 중이에요. 잠시 기다려 주세요.');return;}if(f.size>400000){toast('백업 파일은 400KB 이하여야 해요.');return;}if(!confirm('현재 보관함을 백업 파일로 교체할까요? 먼저 백업을 받아 두세요.'))return;vaultBusy=true;try{const next=await decryptVault(JSON.parse(await f.text()),password);await persist(next);custom=next;render();toast('백업을 복원했어요.');}catch{toast('복원 실패. 같은 비밀번호의 올바른 백업인지 확인해 주세요. 기존 데이터는 유지됩니다.');}finally{vaultBusy=false;idleReset();}};
window.addEventListener('storage',e=>{if((e.key==='drawer-vault'&&e.newValue!==vaultRaw)||e.key===null){lock();if($('manage-dialog').open)$('manage-dialog').close();toast('다른 창에서 보관함을 변경해 안전하게 잠갔어요.');}});
let idle;const idleReset=()=>{clearTimeout(idle);idle=setTimeout(()=>{if(password&&!vaultBusy){lock();if($('manage-dialog').open)$('manage-dialog').close();}},15*60*1000);};['pointerdown','keydown'].forEach(ev=>document.addEventListener(ev,idleReset,{passive:true}));idleReset();
$('help-button').onclick=()=>{cleanup();cleanup=()=>{};$('tool-dialog').classList.remove('presentation');$('tool-title').textContent='교실 서랍 사용 안내';$('tool-description').textContent='기존 앱은 연결하고, 수업 도구는 바로 꺼내 쓰세요.';$('tool-content').replaceChildren();for(const t of ['일기장: 이 PC에서 「교실 서랍 실행.cmd」를 실행하면 허브와 기존 일기장을 함께 시작합니다. 다른 기기에서는 이 PC의 일기장을 열 수 없어요.','내 웹앱: HTTPS 주소를 추가해 보관하세요. 비밀번호는 10자 이상이며 브라우저를 닫거나 15분 동안 조작하지 않으면 보관함이 잠깁니다.','백업: 보관함 관리에서 암호화 파일을 내려받아 보관하세요. 기기를 옮길 때 백업을 가져오고 같은 비밀번호로 해제할 수 있어요.','수업 도구: 학생 이름을 입력하지 않습니다. 번호가 학생과 연결될 수 있으므로 공개 화면 공유에 주의하세요. 뽑기와 모둠 결과는 저장하지 않아요.','기존 Google Apps Script 「교실 도구함」은 배포 미완료 상태라 실행 링크를 등록하지 않았습니다. 하루출결은 개인정보를 다루는 데스크톱 앱이라 포함하지 않았어요.'])$('tool-content').append(node('p','muted',t));$('tool-dialog').showModal();};
render();
